            options={[
              { id: "pipeline", label: "Pipeline seats" },
              { id: "ops", label: "Ops seats" },
            ]}
            onChange={setSiteMeter}
          />
        )}
        {view === "ownership" && (
          <ToggleGroup
            label="Lorenz curve"
            value={curveId}
            options={[
              { id: "owners", label: "Owners" },
              { id: "regions", label: "Regions" },
              { id: "tokens", label: "Tokens" },
            ]}
