"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  LineChart,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  CLOUD_SLICES,
  CONCENTRATION_PATH,
  DELTA_METERS,
  ELECTRICITY_SLICES,
  HEADLINE,
  MARKET_BANDS,
  MARKET_SEATS,
  REGIONS,
  SCOREBOARD,
  SITE_LEDGER,
  SOURCE_NOTE,
  SOURCES,
  TOKEN_BRANDS,
  TOKEN_VS_OWNERSHIP,
  fmtHhi,
  fmtPct,
  fmtSites,
  ownerCurve,
  ownerLadderSorted,
  regionCurve,
  sitePipelineHhi,
  tokenCurve,
  type PerimeterId,
} from "@/data/ai-compute-demand-concentration-202608-data";

// viz-types: delta dumbbells, site stacked bars, Lorenz area+line, ownership bars, cloud donut, electricity donut, path multi-line, market bands, region bars, token bars, token-vs-owner scatter | layout: default

type ViewId = "scoreboard" | "sites" | "ownership" | "tokens";
type CurveId = "owners" | "regions" | "tokens";
type SiteMeter = "pipeline" | "ops";

const TEAL = "#0d9488";
const AMBER = "#f59e0b";
const SKY = "#0ea5e9";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="flex flex-wrap gap-1">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "bg-slate-100 text-slate-700 hover:bg-slate-200"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function AiComputeDemandConcentration202608Dashboard() {
  const [view, setView] = useState<ViewId>("scoreboard");
  const [curveId, setCurveId] = useState<CurveId>("owners");
  const [highlight, setHighlight] = useState<PerimeterId | "all">("all");
  const [siteMeter, setSiteMeter] = useState<SiteMeter>("pipeline");

  const owners = useMemo(() => ownerLadderSorted(), []);
  const oCurve = useMemo(() => ownerCurve(), []);
  const rCurve = useMemo(() => regionCurve(), []);
  const tCurve = useMemo(() => tokenCurve(), []);
  const pipelineHhi = useMemo(() => sitePipelineHhi(), []);

  const activeCurve =
    curveId === "owners" ? oCurve : curveId === "regions" ? rCurve : tCurve;
  const curveLabel =
    curveId === "owners"
      ? "Chip ownership"
      : curveId === "regions"
        ? "Regional AI DC"
        : "Token brands";

  const scoreboardBars = useMemo(() => {
    const rows =
      highlight === "all"
        ? SCOREBOARD
        : SCOREBOARD.filter((s) => s.id === highlight);
    return rows.flatMap((s) => [
      {
        key: `${s.id}-t1`,
        perimeter: s.label,
        metric: "Top-1",
        pct: s.top1Pct,
        fill: s.color,
      },
      {
        key: `${s.id}-t3`,
        perimeter: s.label,
        metric: "Top-3 / twin",
        pct: s.top3Pct,
        fill: `${s.color}99`,
      },
    ]);
  }, [highlight]);

  const pathData = useMemo(
    () =>
      CONCENTRATION_PATH.map((p) => ({
        label: p.label,
        ownerTop1: p.ownerTop1Pct,
        ownerTop3: p.ownerTop3Pct,
        cloudTop3: p.cloudTop3Pct,
        marketTop20: p.marketTop20Pct,
        tokenTop1: p.tokenTop1Pct,
      })),
    [],
  );

  const deltaBars = useMemo(
    () =>
      DELTA_METERS.map((d) => ({
        label: d.label,
        prior: d.prior,
        current: d.current,
        fill: d.color,
      })),
    [],
  );

  const siteStack = useMemo(
    () =>
      SITE_LEDGER.map((s) => ({
        label: s.label,
        share:
          siteMeter === "pipeline" ? s.pipelineSharePct : s.opsSharePct,
        sites: siteMeter === "pipeline" ? s.pipelineSites : s.opsSites,
        fill: s.color,
      })),
    [siteMeter],
  );

  const tokenDelta = useMemo(
    () =>
      TOKEN_BRANDS.filter((t) => t.priorSharePct != null).map((t) => ({
        label: t.label,
        prior: t.priorSharePct as number,
        current: t.sharePct,
        fill: t.color,
      })),
    [],
  );

  return (
    <div
      className="space-y-6"
      data-viz="ai-compute-demand-concentration-202608"
    >
      <div className="rounded-xl border border-amber-200 bg-amber-50/80 px-5 py-4">
        <p className="text-sm font-semibold text-amber-950">
          AI compute demand ??? Aug 2026 concentration lens
        </p>
        <p className="mt-1 text-sm text-amber-900/80">
          Ownership tip stuck: Top-1 {fmtPct(HEADLINE.ownerTop1Pct, 0)} (
          {HEADLINE.ownerTop1Label}), Top-3 {fmtPct(HEADLINE.ownerTop3Pct)}.
          Cloud Top-3 softens to {fmtPct(HEADLINE.cloudTop3Pct, 0)} (
          {HEADLINE.cloudTop3DeltaPp} pp vs Q3). Dual-hub metros hold{" "}
          {fmtPct(HEADLINE.dualHubPct, 0)}; top-20 markets{" "}
          {fmtPct(HEADLINE.marketTop20Pct, 0)} of hyperscale capacity. Pipeline
          expands to {fmtSites(HEADLINE.worldPipelineSites)} sites.
        </p>
      </div>

      <div className="flex flex-col gap-3 sm:flex-row sm:flex-wrap sm:items-center sm:justify-between">
        <ToggleGroup
          label="View"
          value={view}
          options={[
            { id: "scoreboard", label: "Scoreboard" },
            { id: "sites", label: "Sites & cloud" },
            { id: "ownership", label: "Ownership" },
