                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>

            <ChartCard
              title="Top-20 seat composition"
              subtitle={`${HEADLINE.top20UsSeats} US / ${HEADLINE.top20ApacSeats} APAC / ${HEADLINE.top20EuropeSeats} Europe ??? non-US seats down to ${HEADLINE.nonUsInTop20}`}
            >
              <div className="h-64 w-full min-w-0">
